<script setup lang="ts">type Tab={id:string;label:string;disabled?:boolean};defineProps<{modelValue:string;tabs:Tab[]}>();const emit=defineEmits<{'update:modelValue':[v:string]}>();</script><template><div class="vx-tabs" role="tablist"><button v-for="t in tabs" :key="t.id" type="button" role="tab" :disabled="t.disabled" :aria-selected="modelValue===t.id" :tabindex="modelValue===t.id?0:-1" @click="emit('update:modelValue',t.id)">{{t.label}}</button></div></template>